function drawCharacter_spirit(x,y,hp,fr,cfg,isZeroG){
  var bodyCol=cfg.color||"#E8E8FF";
  var eyeCol=cfg.eyeColor||"#4040FF";
  ctx.save();

  // Shadow (if not in zero gravity)
  if(!isZeroG){
    ctx.fillStyle="rgba(0,0,0,0.1)";
    ctx.beginPath();
    ctx.ellipse(x+16,y+30,8,2,0,0,Math.PI*2);
