  ctx.beginPath();
  ctx.ellipse(x+16, y+20+floatY, 6, 12, 0, 0, Math.PI*2);
  ctx.fill();

  // Upper body part - slightly wider
  ctx.beginPath();
  ctx.ellipse(x+16, y+12+floatY, 8, 8, 0, 0, Math.PI*2);
  ctx.fill();

  // Wispy tendrils at bottom
  ctx.beginPath();
  ctx.ellipse(x+12, y+28+floatY, 3, 6, 0.3, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x+20, y+26+floatY, 3, 5, -0.2, 0, Math.PI*2);
  ctx.fill();

  // Binary code flickering effect
  if(Math.random() < 0.3){
    ctx.globalAlpha = 0.4;
    ctx.fillStyle = "#8080FF";
    ctx.font = "6px monospace";
