  ctx.shadowColor = eyeCol;
  ctx.shadowBlur = 4;
  ctx.beginPath();
  ctx.arc(x+12, y+10+floatY, 2, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x+20, y+10+floatY, 2, 0, Math.PI*2);
  ctx.fill();
  ctx.shadowBlur = 0;

  // HP bar
  ctx.fillStyle="#111";
  ctx.fillRect(x,y-8,30,5);
  ctx.fillStyle=cfg.color||"#E8E8FF";
  ctx.fillRect(x,y-8,30*hp,5);

  // Name tag
