    ctx.fillStyle="rgba(0,0,0,0.75)";
    var tw=ctx.measureText(cfg.name).width+10;
    ctx.fillRect(x+16-tw/2,y-20,tw,14);
    ctx.fillStyle=eyeCol;
    ctx.font="bold 9px Fredoka One";
    ctx.textAlign="center";
    ctx.fillText(cfg.name,x+16,y-9);
    ctx.textAlign="left";
  }

  ctx.restore();
}

