function drawCharacter_turkey(x, y, hp, fr, cfg, isZeroG) {
    ctx.save();

    // HP bar
    ctx.fillStyle = "#111";
    ctx.fillRect(x, y - 8, 30, 5);
    ctx.fillStyle = cfg.color || "#8B4513";
    ctx.fillRect(x, y - 8, 30 * hp, 5);

    // Name tag
    if (cfg.name) {
        ctx.fillStyle = "#FFF";
        ctx.font = "8px Arial";
        ctx.fillText(cfg.name, x - 5, y - 12);
    }

    // Animation variables
    const bobOffset = Math.sin(fr * 0.15) * 2;
    const tailGlow = 0.5 + Math.sin(fr * 0.3) * 0.5;
    const formationSway = Math.cos(fr * 0.1) * 3;

    ctx.translate(x + 16 + formationSway, y + 16 + bobOffset);

    // Jet-powered tail feathers with glow
    ctx.shadowColor = "#FF4500";
    ctx.shadowBlur = 8 * tailGlow;

    for (let i = 0; i < 5; i++) {
        const angle = -Math.PI/3 + (i * Math.PI/6);
        const length = 12 + Math.sin(fr * 0.2 + i) * 3;

        ctx.save();
        ctx.rotate(angle);

        // Jet flame effect
        const gradient = ctx.createLinearGradient(0, 0, length, 0);
        gradient.addColorStop(0, "#FF4500");
        gradient.addColorStop(0.5, "#FF6B00");
        gradient.addColorStop(1, "#FF8C00");

        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.ellipse(length/2, 0, length/2, 3, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }

    ctx.shadowBlur = 0;

    // Main turkey body
    ctx.fillStyle = cfg.color || "#8B4513";
    ctx.beginPath();
    ctx.ellipse(0, 2, 10, 12, 0, 0, Math.PI * 2);
    ctx.fill();

    // Turkey head
    ctx.fillStyle = "#A0522D";
    ctx.beginPath();
    ctx.ellipse(0, -8, 6, 7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Proud chest plumage
    ctx.fillStyle = "#CD853F";
    ctx.beginPath();
    ctx.ellipse(2, -2, 8, 6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Waddle stance legs
    ctx.strokeStyle = "#FF8C00";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-4, 12);
    ctx.lineTo(-6, 18);
    ctx.moveTo(4, 12);
    ctx.lineTo(6, 18);
    ctx.stroke();

    // Commanding beak
    ctx.fillStyle = "#FF6B00";
    ctx.beginPath();
    ctx.moveTo(6, -8);
    ctx.lineTo(10, -6);
    ctx.lineTo(6, -4);
    ctx.closePath();
    ctx.fill();

    // Alert commander eyes
    ctx.fillStyle = cfg.eyeColor || "#FF4500";
    ctx.beginPath();
    ctx.ellipse(-2, -10, 2, 3, 0, 0, Math.PI * 2);
    ctx.ellipse(2, -10, 2, 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Focused pupils
    ctx.fillStyle = "#000";
    ctx.beginPath();
    ctx.ellipse(-2, -10, 1, 1.5, 0, 0, Math.PI * 2);
    ctx.ellipse(2, -10, 1, 1.5, 0, 0, Math.PI * 2);
    ctx.fill();

    // Space commander crest
    ctx.fillStyle = "#FF4500";
    ctx.beginPath();
    ctx.moveTo(0, -15);
    ctx.lineTo(-3, -12);
    ctx.lineTo(0, -13);
    ctx.lineTo(3, -12);
    ctx.closePath();
    ctx.fill();

    // Zero gravity floating effect
    if (isZeroG) {
        ctx.rotate(Math.sin(fr * 0.05) * 0.2);
    }

    ctx.restore();
}

